solution = [5, 0, 1, 6, 5, 3, 1, 7, 2, 4, 3, 3, 2, 6, 1, 7, 6, 5, 7, 4, 0, 2, 0, 4, 7, 7, 1, 2, 6, 6, 0, 6, 4, 2, 5, 3, 5, 7, 3, 1, 0, 3, 4, 5, 1, 2, 4, 0, 2, 6, 7, 3, 5, 7, 0, 1, 7, 2, 3, 6, 1, 4, 5, 6, 5, 1, 0, 0, 4, 4, 2, 3, 7, 6, 7, 6, 2, 5, 1, 1, 3, 0, 7, 0, 0, 3, 6, 5, 4, 3, 2, 4, 1, 4, 5, 2, 1, 4, 6, 2, 0, 1, 1, 7, 3, 6, 5, 3, 4, 6, 7, 0, 4, 2, 5, 7, 5, 0, 2, 3, 3, 5, 0, 0, 4, 2, 1, 5, 1, 7, 1, 3, 0, 6, 2, 6, 3, 7, 7, 4, 2, 5, 4, 6, 5, 1, 1, 2, 0, 3, 0, 7, 6, 4, 4, 2, 0, 7, 4, 6, 6, 3, 2, 1, 5, 3, 7, 5, 4, 1, 3, 4, 1, 7, 6, 0, 0, 0, 1, 6, 7, 7, 2, 4, 3, 5, 3, 5, 5, 6, 2, 2]

num_golfers = 24
num_groups = 8
group_size = 3
num_weeks = 8

# Check each week has exactly 3 golfers per group
for w in range(num_weeks):
    week_groups = solution[w*24:(w+1)*24]
    for g in range(num_groups):
        count = week_groups.count(g)
        if count != group_size:
            print(f"Week {w}, Group {g}: {count} golfers (expected {group_size})")

# Check no pair appears together more than once
from collections import defaultdict
pair_count = defaultdict(int)
for w in range(num_weeks):
    week_groups = solution[w*24:(w+1)*24]
    for g in range(num_groups):
        golfers_in_group = [p for p in range(num_golfers) if week_groups[p] == g]
        for i in range(len(golfers_in_group)):
            for j in range(i+1, len(golfers_in_group)):
                pair = (golfers_in_group[i], golfers_in_group[j])
                pair_count[pair] += 1

violations = [(pair, count) for pair, count in pair_count.items() if count > 1]
if violations:
    print(f"Violations: {violations}")
else:
    print("All constraints satisfied!")
    print(f"Total pairs covered: {len(pair_count)} out of {num_golfers*(num_golfers-1)//2}")
